const APP_SCOPE = new URL(self.registration.scope);
// Immutable revisions share storage across updates. Keep older revisions for open pages.
const CACHE_NAME = `workout-check:${APP_SCOPE.pathname}:immutable-v1`;
const known = new Map(ASSETS.map(entry => [new URL(entry.url, APP_SCOPE).href, entry]));
const shell = ASSETS.find(entry => entry.path === 'index.html');
const shellURL = new URL(shell.url, APP_SCOPE).href;

function local(url) { return url.origin === APP_SCOPE.origin && url.pathname.startsWith(APP_SCOPE.pathname); }
function staticRevision(url) {
  const pairs = [...url.searchParams];
  return local(url) && /\.(js|css|png|jpg|webp|svg|json|html)$/.test(url.pathname) &&
    pairs.length === 1 && pairs[0][0] === 'v' && /^[a-f0-9]{64}$/.test(pairs[0][1]);
}
async function stored(key) {
  try { return await (await caches.open(CACHE_NAME)).match(key); } catch (_) { return null; }
}
async function download(entry) {
  const target = new URL(entry.url, APP_SCOPE).href;
  const response = await fetch(new Request(target, { integrity: entry.integrity, cache: 'default' }));
  if (!response.ok || response.type === 'opaque') throw new Error('APP_ASSET_FETCH_FAILED');
  try { await (await caches.open(CACHE_NAME)).put(target, response.clone()); } catch (_) { /* Online use still works if storage is full. */ }
  return response;
}
